  select 'SESSAO_FECHADA',
         coalesce((select string_agg(s.status::text || ' ' || to_char(s.starts_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI') || ' ' || s.duration_minutes || 'min ' || s.price_cents || ' centavos ' || s.capacity || ' vagas', '; ') from sess s), 'nenhuma'),
         case when (select count(*) from sess) = 1 and (select count(*) from sess s where s.status = 'CLOSED' and s.starts_at = '2026-11-23T20:15:00.000Z'::timestamptz and s.duration_minutes = 195 and s.price_cents = 16000 and s.capacity = 24) = 1 then 'OK' else 'FALHOU' end
  union all
  select 'FORA_DAS_LEITURAS_PUBLICAS',
         (select count(*) from public.get_public_event('essencia-lua-cheia'))::text || ' página, ' || ((select count(*) from public.list_open_sessions('essencia-lua-cheia')) + (select count(*) from public.list_public_sessions('essencia-lua-cheia')) + coalesce((select count(*) from sess, lateral public.get_booking_session(sess.id)), 0))::text || ' caminho(s) de reserva',
         case when (select count(*) from public.get_public_event('essencia-lua-cheia')) = 0 and ((select count(*) from public.list_open_sessions('essencia-lua-cheia')) + (select count(*) from public.list_public_sessions('essencia-lua-cheia')) + coalesce((select count(*) from sess, lateral public.get_booking_session(sess.id)), 0)) = 0 then 'OK' else 'FALHOU' end
  union all
  select 'ADMINISTRADOR_DO_ATO',
         (select count(*)::text from public.admin_users au join auth.users u on u.id = au.user_id
    where lower(u.email) = 'almaazulacademy@gmail.com' and au.is_active and au.role = 'ADMIN'),
         case when (select count(*) from public.admin_users au join auth.users u on u.id = au.user_id
    where lower(u.email) = 'almaazulacademy@gmail.com' and au.is_active and au.role = 'ADMIN') = 1 then 'OK' else 'FALHOU' end
  union all
  select 'INTERRUPTOR_LIGADO',
         coalesce((select case when publication_enabled then 'ligado (não é alterado)' else 'desligado' end from public.special_event_settings where singleton), 'ausente'),
         case when (select publication_enabled from public.special_event_settings where singleton) then 'OK' else 'FALHOU' end
  union all
  select 'SEGURANCA_DOS_EVENTOS',
         case when exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'experiences' and policyname = 'events hidden until published')
     and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'sessions' and policyname = 'event sessions hidden until published')
     and exists (select 1 from pg_trigger where tgrelid = 'public.reservations'::regclass and tgname = 'reservations_event_publication_guard')
     and exists (select 1 from pg_trigger where tgrelid = 'public.waitlist_entries'::regclass and tgname = 'waitlist_entries_event_publication_guard')
     and exists (select 1 from pg_proc where proname = 'event_publication_allows' and pronamespace = 'public'::regnamespace) then 'migration 202610310004 aplicada' else 'AUSENTE' end,
         case when exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'experiences' and policyname = 'events hidden until published')
     and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'sessions' and policyname = 'event sessions hidden until published')
     and exists (select 1 from pg_trigger where tgrelid = 'public.reservations'::regclass and tgname = 'reservations_event_publication_guard')
     and exists (select 1 from pg_trigger where tgrelid = 'public.waitlist_entries'::regclass and tgname = 'waitlist_entries_event_publication_guard')
     and exists (select 1 from pg_proc where proname = 'event_publication_allows' and pronamespace = 'public'::regnamespace) then 'OK' else 'FALHOU' end
  union all
  select 'RESERVAS_E_INSCRICOES_DA_EDICAO',
         coalesce((select string_agg(status || '=' || n, ', ' order by status) from (select r.status::text, count(*) n from public.reservations r join sess s on s.id = r.session_id group by 1) x), 'nenhuma reserva')
           || '; ' || (select count(*) from public.waitlist_entries w join sess s on s.id = w.session_id)::text || ' inscrição(ões) na lista'
           || '; ' || coalesce((select public.available_spots(s.id)::text || ' vaga(s) livre(s)' from sess s limit 1), 'sem sessão'),
         case when exists (select 1 from public.reservations r join sess s on s.id = r.session_id) or exists (select 1 from public.waitlist_entries w join sess s on s.id = w.session_id) then 'FALHOU' else 'OK' end
  union all
  select 'TURMAS_REGULARES_SOBREPOSTAS',
         coalesce((select string_agg(e.slug || ' ' || to_char(s.starts_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI') || ' ' || s.status::text, '; ' order by s.starts_at)
          from public.sessions s join public.experiences e on e.id = s.experience_id join public.bases b on b.id = e.base_id
          where e.kind = 'REGULAR' and b.slug = 'concha-acustica' and s.status::text not in ('CANCELLED', 'ARCHIVED')
            and s.starts_at < '2026-11-23T23:30:00.000Z'::timestamptz
            and s.starts_at + make_interval(mins => s.duration_minutes) > '2026-11-23T20:15:00.000Z'::timestamptz), 'nenhuma'),
         case when exists (select 1 from public.sessions s join public.experiences e on e.id = s.experience_id join public.bases b on b.id = e.base_id
          where e.kind = 'REGULAR' and b.slug = 'concha-acustica' and s.status::text not in ('CANCELLED', 'ARCHIVED')
            and s.starts_at < '2026-11-23T23:30:00.000Z'::timestamptz
            and s.starts_at + make_interval(mins => s.duration_minutes) > '2026-11-23T20:15:00.000Z'::timestamptz) then 'ATENCAO' else 'OK' end
  union all
  select 'OUTROS_EVENTOS',
         (select coalesce(count(*)::text || ' evento(s) [' || string_agg(e.slug || '=' || e.status, ', ' order by e.slug) || '] ' || md5(string_agg(e.id::text || e.status || e.editorial_content::text || coalesce((
            select string_agg(s.id::text || s.status::text || s.starts_at::text || s.capacity || s.price_cents || s.duration_minutes, ',' order by s.id)
            from public.sessions s where s.experience_id = e.id), ''), '|' order by e.id)), 'nenhum outro evento')
          from public.experiences e where e.kind = 'EVENT' and e.slug <> 'essencia-lua-cheia'),
         'OK'
  union all
  select 'LISTAGENS_REGULARES',
         (select count(*)::text from public.list_public_regular_experiences()) || ' experiências, ' || (select count(*)::text from public.list_public_regular_catalog()) || ' no catálogo',
         'OK'
  union all
  select 'RESERVAS_POR_STATUS',
         (select string_agg(status || '=' || n, ', ' order by status) from (select status::text, count(*) n from public.reservations group by 1) x),
         'OK'
  union all
  select 'INSCRICOES_DA_LISTA_POR_STATUS',
         coalesce((select string_agg(status || '=' || n, ', ' order by status) from (select status::text, count(*) n from public.waitlist_entries group by 1) x), 'nenhuma'),
         'OK'
)
select check_name, result, status from checks
union all
select 'EVENTO_PUBLICACAO_PREFLIGHT_OK',
       (select count(*) filter (where status = 'FALHOU')::text || ' falha(s), ' || count(*) filter (where status = 'ATENCAO')::text || ' ponto(s) de atenção' from checks),
       case when exists (select 1 from checks where status = 'FALHOU') then 'FALHOU' else 'OK' end;
